Future<void> expectRegion(
  WidgetTester tester,
  StageState state, {
  required StageRegion region,
  required String slug,
  required String id,
  String size = referenceSize,
}) async {
  await pumpStage(tester, state, size: size);
  await expectLater(
    find.byKey(region.key),
    matchesGoldenFile('screen/cases/$slug.$id.png'),
  );
}

